import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/**
 * Billing lock: a workspace whose subscription is not in good standing is
 * read-only. The rule is pure so the server guard, the billing summary and
 * the shell banner all agree on it.
 */

/** Thrown by write paths while the workspace is locked. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`This workspace is read-only until billing is resolved (${reason}).`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * Why the workspace is locked at `now`, or `null` when it is writable. No
 * subscription row, or an `active` one, is writable.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (!subscription) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return reached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
    case "canceled":
      return subscription.cancelAt === null ||
        reached(subscription.cancelAt, now)
        ? "canceled"
        : null;
    default:
      return null;
  }
}

function reached(moment: string, now: Date): boolean {
  const at = new Date(moment).getTime();
  if (Number.isNaN(at)) return false;
  return now.getTime() >= at;
}
